created = updated = 0
for data in ITEMS:
    obj, was_created = MediaItem.objects.update_or_create(
        title=data["title"], media_type=data["media_type"], year=data["year"],
        defaults={**data, "pd_verified": True},
    )
    created += was_created
    updated += not was_created
print(f"seed done: {created} created, {updated} updated, {MediaItem.objects.count()} total")
